# owner: platform
"""Seating charts: students in rows by last name."""

from typing import List

from rosterkit.models import Student

def _sort_key(student: Student):
    return (
        student.last_name.casefold(),
        student.first_name.casefold()
    )

# ---
def seating_rows(
    students: List[Student], seats_per_row: int
) -> List[str]:
    """One text line per row, ordered by last name."""
    if seats_per_row <= 0:
        raise ValueError("seats_per_row must be positive")
    if not students:
        raise ValueError("no students to seat")
    ordered = sorted(students, key=_sort_key)
    lines = []
    for start in range(0, len(ordered), seats_per_row):
        chunk = ordered[start:start + seats_per_row]
        names = " | ".join(
            item.display_name for item in chunk
        )
        lines.append(f"Row {len(lines) + 1}: {names}")
    return lines

