# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student

def make(last, first):
    return Student("id", last, first, "A")

class SeatingTests(unittest.TestCase):
    def test_sorted_by_last_name_and_split_into_rows(self):
        people = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Zane", "Ola")
        ]
        self.assertEqual(
            seating_rows(people, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zane, Ola"
            ]
        )

    def test_first_name_breaks_ties(self):
        people = [make("Lee", "Zed"), make("lee", "Amy")]
        self.assertEqual(
            seating_rows(people, 5),
            ["Row 1: lee, Amy | Lee, Zed"]
        )

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([make("Lee", "Amy")], 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([make("Lee", "Amy")], -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
